def _install_gcu_f64_broadcast_setitem_shim():
    # torch_gcu's broadcast assignment path for "float64" (emulated) tensors
    # bypasses the Double->Float replacement wrapper and dies on a raw Scalar
    # conversion: `inp[:4] = payloads[:, None]` raises
    # "INTERNAL ASSERT FAILED ... Cannot convert ScalarType Double to
    # topsatenDataType_t" (gcu_utils.cpp:243) before the op is ever called.
    # The non-broadcast path works.  Bridge the broadcast case only: read the
    # RHS values at the true element width (torch view(dtype) semantics - a
    # "float64" tensor whose storage was produced under another dtype, e.g. an
    # int64 tensor viewed as float64, holds true fp64 bits, while torch_gcu's
    # packed-fp32 payload convention would scramble them), materialize the
    # broadcast on the host, and delegate to the original non-broadcast
    # setitem with a freshly H2D'd operand.
    if getattr(torch.Tensor.__setitem__, "_flaggems_gcu_f64_shim", False):
        return
    original_setitem = torch.Tensor.__setitem__

    def _is_basic_key(key):
        # Advanced indexing (mask/index tensors) makes self[key] materialize a
        # copy; writing into that copy would silently drop the assignment.
        if key is None or key is Ellipsis or isinstance(key, (slice, int)):
            return True
        if isinstance(key, tuple):
            return all(_is_basic_key(k) for k in key)
        return False

    def _gcu_f64_setitem(self, key, value):
        try:
            if (
                isinstance(value, torch.Tensor)
                and self.dtype == torch.float64
                and value.dtype == torch.float64
                and _is_basic_key(key)
                and self.device.type == "gcu"
                and value.device.type == "gcu"
            ):
                destination = self[key]
                if destination.shape != value.shape:
                    values = (
                        value.contiguous().view(torch.int64).cpu().view(torch.float64)
                    )
                    values = torch.broadcast_to(values, destination.shape).contiguous()
                    return original_setitem(self, key, values.to(self.device))
        except Exception:
            pass
        return original_setitem(self, key, value)

    _gcu_f64_setitem._flaggems_gcu_f64_shim = True
    torch.Tensor.__setitem__ = _gcu_f64_setitem


_install_gcu_f64_broadcast_setitem_shim()


@libentry()
@triton.jit
def canonicalize_nan_kernel(inp, out, n_elements, BLOCK_SIZE: tl.constexpr):
    offsets = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    values = tl.load(inp + offsets, mask=mask)
    values = tl.where(values != values, float("nan"), values)
    tl.store(out + offsets, values, mask=mask)


@libentry()
@triton.jit
def gather_sorted_values_kernel(
    inp, indices, out, n_elements, n_cols, BLOCK_SIZE: tl.constexpr
):
    offsets = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    rows = tl.load(indices + offsets, mask=mask, other=0)
    values = tl.load(inp + rows * n_cols + offsets % n_cols, mask=mask)
    tl.store(out + offsets, values, mask=mask)


@triton.jit
def _bitonic_peer(x, step: tl.constexpr, BC: tl.constexpr, LOGM: tl.constexpr):
    # Partner value along the sort axis: reshape the (BC, M) tile into a
    # [BC, 2, ..., 2] hypercube (one size-2 axis per row bit) and xor-sum the
    # pair, so peer = x ^ pair_xor fetches the lane at row ^ (1 << step).
    shape: tl.constexpr = [BC] + [2] * LOGM
    h = tl.reshape(x, shape)
    pe = tl.xor_sum(h, LOGM - step, keep_dims=True)
    pe = tl.reshape(tl.broadcast_to(pe, shape), (BC, 1 << LOGM))
    return x ^ pe


@libentry()
@triton.jit
def msort_bitonic_tile_kernel(
    inp,
    out,
    n_cols,
    M: tl.constexpr,
    BC: tl.constexpr,
    IS_FLOAT: tl.constexpr,
    KEY_BITS: tl.constexpr,
    IS_SIGNED: tl.constexpr,
    PACK16: tl.constexpr,
):
    # Column (dim-0) sort for many short, power-of-two rows, one launch.
    # Each program owns BC columns: it loads the (BC, M) tile (columns along
    # the minor axis stay memory-contiguous), runs a bitonic network along the
    # row axis and stores the tile back.  With num_warps=1 the pair exchanges
    # stay inside 128-lane vectors for M <= 128, which is why the envelope
    # below is capped there (the generic radix/mradix path stays faster once
    # the network needs cross-vector exchanges, e.g. M = 512).
    #
    # Ordering keys are monotone uint32 maps of the values (sign-fold for
    # floats, sign-bit flip for signed ints), NaNs canonicalized to the top
    # key like the radix path.  fp16/bf16 rows pack key and raw bits into one
    # uint32 lane ((key << 16) | raw), so the network moves a single channel
    # and the original NaN payload bits ride along to the output.  fp32 needs
    # two channels (32-bit key + raw bits) and is therefore capped at M <= 64.
    LOGM: tl.constexpr = M.bit_length() - 1
    pid = tl.program_id(0)
    cols = pid * BC + tl.arange(0, BC)
    rows = tl.arange(0, M)
    cmask = cols < n_cols
    offs_t = rows[None, :] * n_cols + cols[:, None]  # (BC, M)
    mask_t = cmask[:, None]
    x = tl.load(inp + offs_t, mask=mask_t, other=0)
    if IS_FLOAT and PACK16:
        raw = x.to(tl.uint16, bitcast=True).to(tl.uint32)
        SIGN: tl.constexpr = 1 << (KEY_BITS - 1)
        MASKW: tl.constexpr = (1 << KEY_BITS) - 1
        key = tl.where((raw >> (KEY_BITS - 1)) != 0, (~raw) & MASKW, raw ^ SIGN)
        key = tl.where(x != x, MASKW, key)
        key = (key << 16) | raw
    elif IS_FLOAT:
        if KEY_BITS == 16:
            raw = x.to(tl.uint16, bitcast=True).to(tl.uint32)
        else:
            raw = x.to(tl.uint32, bitcast=True)
        SIGN: tl.constexpr = 1 << (KEY_BITS - 1)
        MASKW: tl.constexpr = (1 << KEY_BITS) - 1
        key = tl.where((raw >> (KEY_BITS - 1)) != 0, (~raw) & MASKW, raw ^ SIGN)
        key = tl.where(x != x, MASKW, key)
        val = raw
    else:
        if KEY_BITS == 32:
            raw = x.to(tl.uint32, bitcast=True)
        elif KEY_BITS == 16:
            raw = x.to(tl.uint16, bitcast=True).to(tl.uint32)
        elif KEY_BITS == 8:
            raw = x.to(tl.uint8, bitcast=True).to(tl.uint32)
        else:
            raw = x.to(tl.uint32)
        if IS_SIGNED:
            SIGNI: tl.constexpr = 1 << (KEY_BITS - 1)
            key = raw ^ SIGNI
        else:
            key = raw
    for stage in tl.static_range(1, LOGM + 1):
        for step in tl.static_range(stage - 1, -1, -1):
            pkey = _bitonic_peer(key, step, BC, LOGM)
            if IS_FLOAT and not PACK16:
                pval = _bitonic_peer(val, step, BC, LOGM)
            less = key < pkey
            choose_min = ((rows & (1 << stage)) == 0) == ((rows & (1 << step)) == 0)
            take_peer = tl.where(choose_min[None, :], ~less, less)
            key = tl.where(take_peer, pkey, key)
            if IS_FLOAT and not PACK16:
                val = tl.where(take_peer, pval, val)
    if IS_FLOAT and PACK16:
        res = (key & 0xFFFF).to(tl.uint16).to(x.dtype, bitcast=True)
    elif IS_FLOAT:
        if KEY_BITS == 16:
            res = val.to(tl.uint16).to(x.dtype, bitcast=True)
        else:
            res = val.to(x.dtype, bitcast=True)
    else:
        if IS_SIGNED:
            SIGNR: tl.constexpr = 1 << (KEY_BITS - 1)
            sraw = key ^ SIGNR
        else:
            sraw = key
        if KEY_BITS == 32:
            res = sraw.to(tl.int32, bitcast=True) if IS_SIGNED else sraw.to(tl.uint32)
        elif KEY_BITS == 16:
            res = sraw.to(tl.uint16).to(x.dtype, bitcast=True)
        elif KEY_BITS == 8:
            res = sraw.to(tl.uint8).to(x.dtype, bitcast=True)
        else:
            res = sraw.to(x.dtype)
    offs_m = rows[:, None] * n_cols + cols[None, :]  # (M, BC)
    tl.store(out + offs_m, tl.trans(res), mask=tl.trans(mask_t))


_TILE_DTYPE_BITS = {
    torch.float16: (16, True, False, True),
    torch.bfloat16: (16, True, False, True),
    torch.float32: (32, True, False, False),
    torch.bool: (1, False, False, False),
    torch.int8: (8, False, True, False),
    torch.int16: (16, False, True, False),
    torch.int32: (32, False, True, False),
}


def _msort_tile_params(inp):
    # Envelope of the bitonic tile path: contiguous 2-D-flattenable input with
    # a power-of-two first dimension that fits in-vector pair exchanges.  The
    # fp32 two-channel network only pays off to 64 rows; everything else
    # (including int64 and any non-power-of-two row count) stays on the radix
    # path below.
    #
    # block_cols avoids a compiler layout miscompile of the reshape +
    # xor_sum + broadcast exchange (deterministic wrong values, independent
    # of num_warps): (BC=128, M in {2, 8}) and (BC=32, M=32) silently
    # mis-sort, while BC=64 is correct for every validated M and BC=128 is
    # correct for M in {16, 32, 64, 128}.  The assignment below therefore
    # only pairs BC values with M ranges that the correctness matrix
    # validated (28 shape x dtype combos x 3 repeats per pair).
    n_rows = inp.shape[0]
    if n_rows < 2 or n_rows > 128 or n_rows & (n_rows - 1):
        return None
    spec = _TILE_DTYPE_BITS.get(inp.dtype)
    if spec is None:
        return None
    key_bits, is_float, is_signed, pack16 = spec
    if key_bits == 32 and is_float and n_rows > 64:
        return None
    if inp.numel() >= 2**31:
        return None
    n_cols = inp.numel() // n_rows
    if 8 < n_rows < 64:
        block_cols = 128
    else:
        block_cols = 64
    return n_cols, block_cols, key_bits, is_float, is_signed, pack16


# gcu400: the register bitonic path (tl.sort over a (BLOCK_COLS, BLOCK_ROWS)
# tile) is disabled.  It mis-sorts the padded tail as soon as n_rows needs
# padding (e.g. 63 -> BLOCK_ROWS 64 leaked pad values into the last real row;
# 257 -> 512 wrong for int16/int32) and the float variant additionally cannot
# carry NaN payloads through a 32-bit key space (this backend truncates tl.sort
# on int64 to 32 bits).  Everything now goes through the radix path below
# (sort_stable + gather of the original values), which preserves NaN payloads
# and is shape-independent.


def _msort_contiguous(inp, out):
    if inp.ndim == 0:
        copy_(out, inp)
        return

    n_rows = inp.shape[0]
    if inp.numel() == 0 or n_rows == 1:
        copy_(out, inp)
        return

    tile = _msort_tile_params(inp)
    if tile is not None:
        n_cols, block_cols, key_bits, is_float, is_signed, pack16 = tile
        with torch_device_fn.device(inp.device):
            msort_bitonic_tile_kernel[(triton.cdiv(n_cols, block_cols),)](
                inp,
                out,
                n_cols,
                M=n_rows,
                BC=block_cols,
                IS_FLOAT=is_float,
                KEY_BITS=key_bits,
                IS_SIGNED=is_signed,
                PACK16=pack16,
                num_warps=1,
            )
        return

    radix_inp = inp
    if inp.dtype.is_floating_point:
        radix_inp = torch.empty_like(inp)
        block_size = 1024
        with torch_device_fn.device(inp.device):
            canonicalize_nan_kernel[(triton.cdiv(inp.numel(), block_size),)](
                inp, radix_inp, inp.numel(), BLOCK_SIZE=block_size
            )
    values, indices = sort_stable(radix_inp, stable=False, dim=0, descending=False)
    if inp.dtype.is_floating_point:
        indices = contiguous(indices)
        with torch_device_fn.device(inp.device):
            gather_sorted_values_kernel[(triton.cdiv(inp.numel(), 1024),)](
                inp,
                indices,
                out,
                inp.numel(),
                inp.numel() // n_rows,
                BLOCK_SIZE=1024,
            )
    else:
        copy_(out, values)


def msort(inp):
    logger.debug("GEMS_ENFLAME MSORT")
    if inp.is_complex():
        raise RuntimeError('"msort" not implemented for complex dtypes')
    out = torch.empty_like(inp, memory_format=torch.preserve_format)
    msort_out(inp, out=out)
    return out


def msort_out(inp, *, out):
    logger.debug("GEMS_ENFLAME MSORT.OUT")
    if inp.is_complex():
        raise RuntimeError('"msort" not implemented for complex dtypes')
    if out.dtype != inp.dtype:
        raise RuntimeError(
            f"Expected out tensor to have dtype {inp.dtype}, but got {out.dtype} instead"
        )
    if out.device != inp.device:
        raise RuntimeError(
            f"Expected out tensor to have device {inp.device}, but got {out.device} instead"
        )
    if inp.dtype == torch.float64:
        # gcu400 has no fp64 datapath: torch_gcu stores "float64" tensors as a
        # compact fp32 payload (8N-byte buffer, first 4N bytes hold numel fp32
        # values) and swaps in Float replace at the aten boundary.  Bridge
        # through that boundary instead of touching fp64 storage from Triton:
        # the .to(float32) cast unwraps the real fp32 payload (it also
        # snapshots inp up front, so out may alias inp), the existing fp32
        # radix pipeline does all the sorting, and the copy_ back stores the
        # payload compactly the same way native aten does.  Direct Triton
        # loads/stores on "float64" storages (fp32-alias/int32/int64 views
        # alike) are fine in isolation but poison the GCU context when
        # interleaved with native fp64-emulated kernels (device Sip
        # exception -> KMD abort), so they must stay out of this path.
        if out.shape != inp.shape:
            out.resize_(inp.shape)
        inp32 = inp.to(torch.float32)
        if not inp32.is_contiguous():
            inp32 = contiguous(inp32)
        out32 = torch.empty_like(inp32)
        _msort_contiguous(inp32, out32)
        out.copy_(out32)
        return out

    if (
        inp.numel()
        and inp.untyped_storage().data_ptr() == out.untyped_storage().data_ptr()
    ):
        # Preserve all source values before resize or any cross-program stores.
        source = torch.empty(inp.shape, dtype=inp.dtype, device=inp.device)
        copy_(source, inp)
        inp = source
    if out.shape != inp.shape:
        out.resize_(inp.shape)

    if inp.is_contiguous() and out.is_contiguous():
        _msort_contiguous(inp, out)
    else:
        contiguous_inp = contiguous(inp)
        contiguous_out = torch.empty_like(contiguous_inp)
        _msort_contiguous(contiguous_inp, contiguous_out)
        copy_(out, contiguous_out)
    return out
